/// <summary>
/// The <c>METBulkWFWorkItemManagerMainController</c> class for the batch job to approve / reject / delegate free text invoices.
/// </summary>
/// Added for CFR4 bulk approval AR invoice
public class METBulkWFWorkItemManagerMainController extends SysOperationServiceController implements BatchRetryable
{
}

Method.Source:
/// <summary>
/// Runs the class with the specified arguments.
/// </summary>
/// <param name="_args">The arguments passed to the subtask.</param>
public static void main(Args _args)
{
    METBulkWFWorkItemManagerMainController controller = new METBulkWFWorkItemManagerMainController();
    controller.startOperation();
}

/// <summary>
/// Specifies if the batch task is retryable for transient exceptions.
/// </summary>
/// <returns>
/// <c>true</c> if the batch task is retryable; otherwise, <c>false</c>.
/// </returns>
[Hookable(false)]
final boolean isRetryable()
{
    return true;
}

/// <summary>
/// Creates a new instance of the <c>METBulkWFWorkItemManagerMainController</c> class from arguments.
/// </summary>
/// <returns>A new instance of the <c>METBulkWFWorkItemManagerMainController</c> class.</returns>
public static METBulkWFWorkItemManagerMainController newFromArgs()
{
    identifierName            className     = classStr(METBulkWFWorkItemManagerMainService);
    identifierName            methodName    = methodStr(METBulkWFWorkItemManagerMainService, execute);
    SysOperationExecutionMode executionMode = SysOperationExecutionMode::ScheduledBatch;

    METBulkWFWorkItemManagerMainController controller = new METBulkWFWorkItemManagerMainController(className, methodName, executionMode);

    return controller;
}

/// <summary>
/// Auto schedule the batch job.
/// </summary>
/// <param name = "_formDS">Contains formDataSource.</param>
/// <param name = "_workflowComment">Contains workflowComment.</param>
/// <param name = "_actionType">Contains workflowActionType.</param>
/// <param name = "_userId">Contains userId.</param>
public static void scheduleBatch(
    FormDatasource              _formDS, 
    WorkflowComment             _workflowComment,
    WorkflowWorkItemActionType  _actionType,
    UserId                      _userId)
{
    METBulkWFWorkItemManagerMainContract contract;
    QueryBuildRange						 qbrRecId;
    QueryBuildDataSource				 qbdsCustInvoiceTable;

    SysRecurrenceData sysRecurrenceData = SysRecurrence::defaultRecurrence();
    sysRecurrenceData = SysRecurrence::setRecurrenceStartDateTime(sysRecurrenceData, DateTimeUtil::utcNow());
    sysRecurrenceData = SysRecurrence::setRecurrenceEndAfter(sysRecurrenceData, 1);

    METBulkWFWorkItemManagerMainController controller = METBulkWFWorkItemManagerMainController::newFromArgs();

    controller.parmDialogCaption("@MET:METFTIBulkWFOperation");
    // create new query
    Query query = new query(queryStr(METBulkWFFreeTextInvoiceManager));


    if (_formDS.anyMarked())
    {
        Common datasourceRecord = _formDS.getFirst(true);

        while (datasourceRecord)
        {
            // add range
            if (!qbrRecId)
            {
                qbdsCustInvoiceTable = query.dataSourceTable(tableNum(CustInvoiceTable));

                if (qbdsCustInvoiceTable)
                {
                    qbrRecId = SysQuery::findOrCreateRange(qbdsCustInvoiceTable, fieldNum(CustInvoiceTable, RecId));
                }
            }

            if (qbrRecId)
            {
                if (strLen(qbrRecId.value()) + strLen(int642Str(datasourceRecord.RecId)) + 1 > 255)
                {
                    qbrRecId = qbdsCustInvoiceTable.addRange(fieldNum(CustInvoiceTable, RecId));
                }

                qbrRecId.value(queryRangeConcat(qbrRecId.value(), datasourceRecord.RecId));
            }

            datasourceRecord = _formDS.getNext();
        }
    }

    contract = controller.getDataContractObject();
    contract.setQuery(query);
    contract.parmWorkFlowComment(_workflowComment);
    contract.parmNoOfThreads(SalesParameters::find().METBulkWorkflowNoOfThreads);
    contract.parmWorkflowActionType(_actionType);
    contract.parmUserId(_userId);

    // set up the recurrence information
    BatchInfo batchInfo = controller.batchInfo();

    batchInfo.parmCaption("@MET:METFTIBulkWFOperation");

    batchInfo.parmRecurrenceData(sysRecurrenceData);

    // This will add the job to the batch table
    controller.parmExecutionMode(SysOperationExecutionMode::ScheduledBatch);
    controller.doBatch();
}
